CREATE TABLE capacity_reservation_samples (reservation_id INTEGER NOT NULL REFERENCES capacity_reservations (id), sample_generation_id TEXT NOT NULL UNIQUE CHECK (length(sample_generation_id) = 32 AND sample_generation_id NOT GLOB '*[^0-9a-f]*'), purpose TEXT NOT NULL CHECK (purpose IN ('initial', 'resume')), PRIMARY KEY (reservation_id, sample_generation_id));
CREATE TABLE capacity_reservations (id INTEGER PRIMARY KEY AUTOINCREMENT, intent_id INTEGER NOT NULL REFERENCES connection_intents (id), connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), assignment_key TEXT NOT NULL CHECK (length(assignment_key) BETWEEN 1 AND 1024), engine_id TEXT NOT NULL CHECK (length(engine_id) BETWEEN 1 AND 128), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), binding_digest TEXT NOT NULL CHECK (length(binding_digest) = 64 AND binding_digest NOT GLOB '*[^0-9a-f]*'), sample_generation_id TEXT, cpu_millicores INTEGER NOT NULL CHECK (cpu_millicores > 0), memory_bytes INTEGER NOT NULL CHECK (memory_bytes > 0), state TEXT NOT NULL CHECK (state IN ('reserved', 'uncertain', 'recovering', 'released')), remote_cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (remote_cleanup_proven IN (0, 1)), local_cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (local_cleanup_proven IN (0, 1)), CHECK (state != 'released' OR (remote_cleanup_proven = 1 AND local_cleanup_proven = 1)));
CREATE TABLE completion_cleanup (intent_id INTEGER PRIMARY KEY REFERENCES intents (id), scale_set_id INTEGER NOT NULL, runner_request_id INTEGER NOT NULL, runner_id INTEGER NOT NULL, runner_name TEXT NOT NULL, runner_absent INTEGER NOT NULL DEFAULT 0 CHECK (runner_absent IN (0, 1)), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), claim_generation INTEGER NOT NULL DEFAULT 0 CHECK (claim_generation >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0), UNIQUE (scale_set_id, runner_request_id), UNIQUE (scale_set_id, runner_id), UNIQUE (scale_set_id, runner_name));
CREATE TABLE completion_inbox (scale_set_id INTEGER NOT NULL CHECK (scale_set_id > 0), message_id INTEGER NOT NULL CHECK (message_id >= 0), raw_body TEXT NOT NULL CHECK (length(CAST(raw_body AS BLOB)) BETWEEN 1 AND 262144), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), PRIMARY KEY (scale_set_id, message_id));
CREATE TABLE connection_completion_cleanup (intent_id INTEGER PRIMARY KEY REFERENCES connection_intents (id), connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), scale_set_id INTEGER NOT NULL CHECK (scale_set_id > 0), runner_request_id INTEGER NOT NULL CHECK (runner_request_id > 0), runner_id INTEGER NOT NULL CHECK (runner_id > 0), runner_name TEXT NOT NULL, runner_absent INTEGER NOT NULL DEFAULT 0 CHECK (runner_absent IN (0, 1)), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), claim_generation INTEGER NOT NULL DEFAULT 0 CHECK (claim_generation >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0), UNIQUE (connection_id, scale_set_id, runner_request_id), UNIQUE (connection_id, scale_set_id, runner_id), UNIQUE (connection_id, scale_set_id, runner_name));
CREATE TABLE connection_completion_inbox (connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), scale_set_id INTEGER NOT NULL CHECK (scale_set_id > 0), message_id INTEGER NOT NULL CHECK (message_id >= 0), raw_body TEXT NOT NULL CHECK (length(CAST(raw_body AS BLOB)) BETWEEN 1 AND 262144), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), PRIMARY KEY (connection_id, scale_set_id, message_id));
CREATE TABLE connection_intents (id INTEGER PRIMARY KEY AUTOINCREMENT, connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), kind TEXT NOT NULL, subject TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('pending', 'done', 'uncertain', 'failed')), cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (cleanup_proven IN (0, 1)), docker_id TEXT, github_runner_id TEXT, dind_id TEXT, worker_volume TEXT, scale_set_id INTEGER, runner_request_id INTEGER, runner_name TEXT, acquire_attempted INTEGER NOT NULL DEFAULT 0 CHECK (acquire_attempted IN (0, 1)), acquire_resolved INTEGER NOT NULL DEFAULT 0 CHECK (acquire_resolved IN (0, 1)), acquired INTEGER NOT NULL DEFAULT 0 CHECK (acquired IN (0, 1)), jit_requested INTEGER NOT NULL DEFAULT 0 CHECK (jit_requested IN (0, 1)), docker_engine_id TEXT, launch_phase TEXT, launch_id TEXT, assignment_key TEXT, seed_generation_id TEXT, runner_completed INTEGER NOT NULL DEFAULT 0 CHECK (runner_completed IN (0, 1)), worker_cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (worker_cleanup_proven IN (0, 1)));
CREATE TABLE connection_launch_recovery (intent_id INTEGER PRIMARY KEY REFERENCES connection_intents (id), connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), generation INTEGER NOT NULL DEFAULT 0 CHECK (generation >= 0), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0));
CREATE TABLE connection_runtime_bindings (connection_id TEXT NOT NULL PRIMARY KEY REFERENCES connection_scopes (connection_id), scale_set_id INTEGER, scale_set_name TEXT, set_ownership TEXT CHECK (set_ownership IS NULL OR set_ownership IN ('created', 'adopted')), engine_id TEXT, docker_endpoint TEXT, platform TEXT, CHECK ((scale_set_id IS NULL AND scale_set_name IS NULL AND set_ownership IS NULL) OR (scale_set_id > 0 AND length(scale_set_name) BETWEEN 1 AND 128 AND set_ownership IS NOT NULL)), CHECK ((engine_id IS NULL AND docker_endpoint IS NULL AND platform IS NULL) OR (length(engine_id) BETWEEN 1 AND 128 AND length(docker_endpoint) BETWEEN 1 AND 4096 AND length(platform) BETWEEN 1 AND 64)));
CREATE TABLE connection_scopes (connection_id TEXT NOT NULL PRIMARY KEY CHECK (length(connection_id) BETWEEN 1 AND 64 AND connection_id NOT GLOB '*[^a-z0-9._-]*' AND substr(connection_id, 1, 1) != '-' AND substr(connection_id, -1, 1) != '-' AND instr(connection_id, '..') = 0), identity TEXT NOT NULL CHECK (length(CAST(identity AS BLOB)) BETWEEN 1 AND 1048576), retired INTEGER NOT NULL DEFAULT 0 CHECK (retired IN (0, 1)));
CREATE TABLE guest_probe_owner (id INTEGER PRIMARY KEY CHECK (id = 1), owner_token TEXT NOT NULL CHECK (length(owner_token) = 32 AND owner_token NOT GLOB '*[^0-9a-f]*'));
CREATE TABLE host_capacity_policy (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), max_jobs INTEGER NOT NULL CHECK (max_jobs > 0), max_cpu_millicores INTEGER NOT NULL CHECK (max_cpu_millicores > 0), max_memory_bytes INTEGER NOT NULL CHECK (max_memory_bytes > 0));
CREATE TABLE intents (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, subject TEXT NOT NULL, state TEXT NOT NULL, docker_id TEXT, github_runner_id TEXT, cleanup_proven INTEGER NOT NULL DEFAULT 0, dind_id TEXT, launch_id TEXT, assignment_key TEXT, seed_generation_id TEXT, acquire_attempted INTEGER NOT NULL DEFAULT 0, acquire_resolved INTEGER NOT NULL DEFAULT 0, acquired INTEGER NOT NULL DEFAULT 0, jit_requested INTEGER NOT NULL DEFAULT 0, runner_completed INTEGER NOT NULL DEFAULT 0, worker_cleanup_proven INTEGER NOT NULL DEFAULT 0, worker_volume TEXT, scale_set_id INTEGER, runner_request_id INTEGER, runner_name TEXT, docker_engine_id TEXT, launch_phase TEXT);
CREATE TABLE journal_meta (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), instance_id TEXT NOT NULL, engine_id TEXT, revision INTEGER NOT NULL DEFAULT 0, lineage_pinned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE launch_recovery (intent_id INTEGER PRIMARY KEY REFERENCES intents (id), generation INTEGER NOT NULL DEFAULT 0 CHECK (generation >= 0), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0));
CREATE TABLE resource_probe_operations (operation_id TEXT PRIMARY KEY CHECK (length(operation_id) = 32 AND operation_id NOT GLOB '*[^0-9a-f]*'), instance_id TEXT NOT NULL, engine_id TEXT NOT NULL, docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), source_revision TEXT NOT NULL CHECK (length(source_revision) = 40 AND source_revision NOT GLOB '*[^0-9a-f]*'), runtime_image_id TEXT NOT NULL, image_binding_digest TEXT NOT NULL CHECK (length(image_binding_digest) = 64 AND image_binding_digest NOT GLOB '*[^0-9a-f]*'), operation_name TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK (role = 'resource-probe'), projection_digest TEXT NOT NULL CHECK (length(projection_digest) = 64 AND projection_digest NOT GLOB '*[^0-9a-f]*'), phase TEXT NOT NULL CHECK (phase IN ('prepared', 'create_requested', 'container_created', 'start_requested', 'started', 'wait_requested', 'waited', 'logs_requested', 'output_observed', 'stop_requested', 'remove_requested', 'removed', 'aborted', 'quarantined')), container_id TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS capacity_reservation_assignment ON capacity_reservations (connection_id, assignment_key);
CREATE UNIQUE INDEX IF NOT EXISTS capacity_reservation_intent ON capacity_reservations (intent_id);
CREATE INDEX IF NOT EXISTS completion_inbox_due ON completion_inbox (retry_after, scale_set_id, message_id);
CREATE INDEX IF NOT EXISTS connection_completion_due ON connection_completion_cleanup (retry_after, lease_until, connection_id, intent_id);
CREATE INDEX IF NOT EXISTS connection_completion_inbox_due ON connection_completion_inbox (connection_id, retry_after, scale_set_id, message_id);
CREATE UNIQUE INDEX IF NOT EXISTS connection_intent_assignment_key ON connection_intents (connection_id, assignment_key) WHERE assignment_key IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS connection_intent_launch_id ON connection_intents (launch_id) WHERE launch_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS connection_intent_live ON connection_intents (connection_id, kind, subject) WHERE state != 'failed' AND cleanup_proven = 0;
CREATE UNIQUE INDEX IF NOT EXISTS connection_intent_request ON connection_intents (connection_id, scale_set_id, runner_request_id) WHERE kind = 'launch' AND scale_set_id IS NOT NULL AND runner_request_id IS NOT NULL AND cleanup_proven = 0;
CREATE UNIQUE INDEX IF NOT EXISTS connection_intent_runner_name ON connection_intents (connection_id, scale_set_id, runner_name) WHERE kind = 'launch' AND scale_set_id IS NOT NULL AND runner_name IS NOT NULL AND cleanup_proven = 0;
CREATE INDEX IF NOT EXISTS connection_launch_recovery_due ON connection_launch_recovery (connection_id, retry_after, lease_until, intent_id);
CREATE UNIQUE INDEX IF NOT EXISTS intents_completion_name ON intents (kind, scale_set_id, runner_name) WHERE kind = 'launch' AND scale_set_id IS NOT NULL AND runner_name IS NOT NULL AND cleanup_proven = 0;
CREATE UNIQUE INDEX IF NOT EXISTS intents_completion_request ON intents (kind, scale_set_id, runner_request_id) WHERE kind = 'launch' AND scale_set_id IS NOT NULL AND runner_request_id IS NOT NULL AND cleanup_proven = 0;
CREATE INDEX IF NOT EXISTS launch_recovery_due ON launch_recovery (retry_after, lease_until, intent_id);
CREATE UNIQUE INDEX IF NOT EXISTS resource_probe_one_active ON resource_probe_operations (role) WHERE phase NOT IN ('removed', 'aborted');
CREATE UNIQUE INDEX IF NOT EXISTS unique_active_assignment_key ON intents (assignment_key) WHERE assignment_key IS NOT NULL AND cleanup_proven = 0;
CREATE UNIQUE INDEX IF NOT EXISTS unique_launch_id ON intents (launch_id) WHERE launch_id IS NOT NULL;
CREATE TRIGGER IF NOT EXISTS capacity_reservation_samples_revision_delete AFTER DELETE ON capacity_reservation_samples BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS capacity_reservation_samples_revision_insert AFTER INSERT ON capacity_reservation_samples BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS capacity_reservation_samples_revision_update AFTER UPDATE ON capacity_reservation_samples BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS completion_cleanup_revision_delete AFTER DELETE ON completion_cleanup BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS completion_cleanup_revision_insert AFTER INSERT ON completion_cleanup BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS completion_cleanup_revision_update AFTER UPDATE ON completion_cleanup BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_completion_cleanup_revision_delete AFTER DELETE ON connection_completion_cleanup BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_completion_cleanup_revision_insert AFTER INSERT ON connection_completion_cleanup BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_completion_cleanup_revision_update AFTER UPDATE ON connection_completion_cleanup BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_completion_inbox_revision_delete AFTER DELETE ON connection_completion_inbox BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_completion_inbox_revision_insert AFTER INSERT ON connection_completion_inbox BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_completion_inbox_revision_update AFTER UPDATE ON connection_completion_inbox BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_launch_recovery_revision_delete AFTER DELETE ON connection_launch_recovery BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_launch_recovery_revision_insert AFTER INSERT ON connection_launch_recovery BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS connection_launch_recovery_revision_update AFTER UPDATE ON connection_launch_recovery BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS intents_revision_delete AFTER DELETE ON intents BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS intents_revision_insert AFTER INSERT ON intents BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS intents_revision_update AFTER UPDATE ON intents BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER journal_lineage_revision AFTER UPDATE OF instance_id, engine_id, lineage_pinned ON journal_meta WHEN OLD.instance_id IS NOT NEW.instance_id OR OLD.engine_id IS NOT NEW.engine_id OR OLD.lineage_pinned IS NOT NEW.lineage_pinned BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS resource_probe_revision_delete AFTER DELETE ON resource_probe_operations BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS resource_probe_revision_insert AFTER INSERT ON resource_probe_operations BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER IF NOT EXISTS resource_probe_revision_update AFTER UPDATE ON resource_probe_operations BEGIN UPDATE journal_meta SET revision = revision + 1 WHERE singleton = 1; END;
